37	// certFooterResults is checkResults plus five certificates covering each way a
38	// row can end: DOWN by proxy, DOWN by x509, OK, close to expiry, expired.
39	func certFooterResults() []status.ComponentStatus {
40		good, soon, expired := 90, 3, -2
41		return append(checkResults(),
42			status.ComponentStatus{Name: "cert-proxy", Type: status.TypeSSL, Target: "proxied.example.com:443", Status: status.StatusDown, Error: proxyRefused},
43			status.ComponentStatus{Name: "cert-x509", Type: status.TypeSSL, Target: "selfsigned.example.com:443", Status: status.StatusDown, Error: x509Failure},
44			status.ComponentStatus{Name: "cert-ok", Type: status.TypeSSL, Target: "ok.example.com:443", Status: status.StatusOK, SSLDaysLeft: &good},
45			status.ComponentStatus{Name: "cert-soon", Type: status.TypeSSL, Target: "soon.example.com:443", Status: status.StatusError, Error: "expires in 3 days", SSLDaysLeft: &soon},
46			status.ComponentStatus{Name: "cert-expired", Type: status.TypeSSL, Target: "expired.example.com:443", Status: status.StatusError, Error: "certificate expired", SSLDaysLeft: &expired},
47		)
48	}
