56	// onCertificate opens the Certificates tab and puts the cursor on a row by name.
57	// The cursor is moved with SetCursor because the display order (sorting) is not
58	// what these tests are about.
59	func onCertificate(t *testing.T, m Model, name string) Model {
60		t.Helper()
61		if m.activeTab != TabCertificates {
62			m = feed(t, m, testutil.Key("tab"))
63		}
64		for i, c := range m.sslTable.Visible() {
65			if c.Name == name {
66				m.sslTable.SetCursor(i)
67				if sel, ok := m.sslTable.Selected(); !ok || sel.Name != name {
68					t.Fatalf("fixture error: cursor on row %d selects %+v, want %q", i, sel, name)
69				}
70				return m
71			}
72		}
73		t.Fatalf("fixture error: no certificate row named %q", name)
74		return m
75	}
