84	func TestFooterCarriesTheSelectedCertificatesProxyFailure(t *testing.T) {
85		m := onCertificate(t, certFooterModel(t), "cert-proxy")
86	
87		want := "cert-proxy " + theme.IconChevronRight + " " + proxyRefused
88		st := m.status()
89		if st.Text != want || st.Level != components.LevelError {
90			t.Errorf("status() = {Text: %q, Level: %v}, want {%q, LevelError}", st.Text, st.Level, want)
91		}
92		if st.Activity {
93			t.Error("status().Activity = true, a failed row is not a load")
94		}
95	
96		footer := m.RenderFooter(160)
97		if got := ansi.Strip(footer); !strings.Contains(got, want) {
98			t.Errorf("footer = %q, want it to contain %q", got, want)
99		}
100		if !strings.Contains(footer, errorSGR()) {
101			t.Error("the message is not rendered with the footer error style (ColorFooterError)")
102		}
103	}
