122	// render, not remembered from the last check.
123	func TestFooterFollowsTheCertificateCursor(t *testing.T) {
124		m := onCertificate(t, certFooterModel(t), "cert-proxy")
125		if !strings.Contains(footerText(m), proxyRefused) {
