141	func TestFooterHasNoFailureTextForARowThatIsNotDown(t *testing.T) {
142		// "cert-soon" and "cert-expired" are StatusError with an Error string: the
143		// expiry states stay carried by the columns (plan, step 4), only DOWN counts.
144		// "cert" (the fixture's StatusWarning row) has no Error at all.
145		for _, name := range []string{"cert-ok", "cert-soon", "cert-expired", "cert"} {
146			t.Run(name, func(t *testing.T) {
147				m := onCertificate(t, certFooterModel(t), name)
148	
149				if st := m.status(); st.Text != "" || st.Level != components.LevelInfo {
150					t.Errorf("status() = %+v on %s, want the empty status", st, name)
151				}
152				got := footerText(m)
153				for _, text := range []string{"expires in", "certificate expired", proxyRefused, x509Failure} {
154					if strings.Contains(got, text) {
155						t.Errorf("footer = %q on %s, must not contain %q", got, name, text)
156					}
157				}
158				if strings.Contains(m.RenderFooter(160), errorSGR()) {
159					t.Errorf("footer on %s carries the Error style, want none", name)
160				}
161			})
162		}
163	}
