165	func TestFooterIgnoresADownRowWithNoErrorText(t *testing.T) {
166		results := append(certFooterResults(), status.ComponentStatus{
167			Name: "cert-mute", Type: status.TypeSSL, Target: "mute.example.com:443", Status: status.StatusDown,
