178	// The Monitors tab is unchanged: its DOWN row ("api") is not announced.
179	func TestFooterIsUnchangedOnTheMonitorsTab(t *testing.T) {
180		m := certFooterModel(t)
181		if m.activeTab != TabMonitors {
182			t.Fatal("fixture error: the model does not open on the Monitors tab")
183		}
184		// Put the cursor on the DOWN monitor.
185		for i, c := range m.monitorTable.Visible() {
186			if c.Name == "api" {
187				m.monitorTable.SetCursor(i)
188			}
189		}
190		if sel, _ := m.monitorTable.Selected(); sel.Name != "api" || sel.Status != status.StatusDown {
191			t.Fatalf("fixture error: selected monitor = %+v, want the DOWN api row", sel)
192		}
193	
194		if st := m.status(); st.Text != "" || st.Level != components.LevelInfo {
195			t.Errorf("status() = %+v on a DOWN monitor, want the empty status", st)
196		}
197		if got := footerText(m); strings.Contains(got, "connection refused") {
198			t.Errorf("footer = %q, a monitor failure must not reach the footer", got)
199		}
200	
201		// A DOWN certificate is not announced while the Monitors tab is showing,
202		// even though sslTable still holds the cursor.
203		for i, c := range m.sslTable.Visible() {
204			if c.Name == "cert-proxy" {
205				m.sslTable.SetCursor(i)
206			}
207		}
208		if got := footerText(m); strings.Contains(got, proxyRefused) {
209			t.Errorf("footer = %q on the Monitors tab, want no certificate failure", got)
210		}
211	}
