240	// so a fresh check that clears the failure clears the footer too.
241	func TestFooterFollowsTheNextCheck(t *testing.T) {
242		m := onCertificate(t, certFooterModel(t), "cert-proxy")
243	
244		fixed := certFooterResults()
245		for i := range fixed {
246			if fixed[i].Name == "cert-proxy" {
