259	// Rule 128 order, step 1: the check's own status comes first.
260	func TestFooterCheckingKeepsPriorityOverACertificateFailure(t *testing.T) {
261		m := onCertificate(t, certFooterModel(t), "cert-proxy")
262		m, _ = step(t, m, testutil.Key("ctrl+r"))
263		if !m.checking {
264			t.Fatal("fixture error: ctrl+r started no check")
265		}
266	
267		wantChecking(t, m, "a check in progress over a DOWN certificate")
268		got := footerText(m)
269		if !strings.Contains(got, "Checking components...") || strings.Contains(got, proxyRefused) {
270			t.Errorf("footer = %q during a check, want only \"Checking components...\"", got)
271		}
272	}
