274	// Rule 128 order, step 2: a timed message is shown before any derived status.
275	func TestFooterTimedMessageComesBeforeACertificateFailure(t *testing.T) {
276		m := onCertificate(t, certFooterModel(t), "cert-proxy")
277		_ = m.footer.Warn("Copied to clipboard") // the Cmd carries the 3 s timer; never run it
278	
279		got := footerText(m)
280		if !strings.Contains(got, "Copied to clipboard") {
281			t.Errorf("footer = %q, want the timed message", got)
282		}
283		if strings.Contains(got, proxyRefused) {
284			t.Errorf("footer = %q, the certificate failure must not show over a timed message", got)
285		}
286	
287		// Once the message is gone, the failure is still there. Clear is called on
288		// the component because Update never offers a ClearFooterMsg to it (see the
289		// report: footer.Handle is reached only from handleMonitorOperations).
290		m.footer.Clear()
291		if !strings.Contains(footerText(m), proxyRefused) {
292			t.Errorf("footer = %q after the timed message expired, want the failure back", footerText(m))
293		}
294	}
