296	// The form's validation status stays ahead of the failure, as it is today.
297	func TestFooterFormValidationComesBeforeACertificateFailure(t *testing.T) {
298		m := onCertificate(t, certFooterModel(t), "cert-proxy")
299		m = feed(t, m, testutil.Key(keymap.New))
300		for i := 0; i < 4; i++ {
301			m = feed(t, m, testutil.Key("down"))
302		}
303		m = feed(t, m, testutil.Key("enter"))
304	
305		got := footerText(m)
306		if !strings.Contains(got, "Name is required") {
307			t.Fatalf("fixture error: the refused submit shows %q, want the Name error", got)
308		}
309		if strings.Contains(got, proxyRefused) {
310			t.Errorf("footer = %q with the form open, want the validation message only", got)
311		}
312	}
