314	// The line is one line: a long failure is truncated, never wrapped (Rule 124).
315	func TestFooterCertificateFailureStaysOnOneLine(t *testing.T) {
316		long := "proxy: " + strings.Repeat("unreachable ", 40)
317		results := certFooterResults()
318		for i := range results {
319			if results[i].Name == "cert-proxy" {
320				results[i].Error = long
321			}
322		}
323		m := feed(t, newTestModel(t, certFooterConfigs()...), CheckCompleteMsg{Components: results, Timestamp: time.Now()})
